pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, address receiver, address owner) public {
        vm.assume(receiver != address(0));
        vm.assume(receiver.code.length == 0);
        vm.assume(receiver != address(c));
        amount = bound(amount, 1, 1 ether);
        vm.deal(address(c), amount);
        uint256 before = address(c).balance;
        vm.prank(address(this));
        bool ok;
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }
        assertTrue(ok && address(c).balance == before - amount);
    }
}
